mapper.select:
SELECT id, product_key, model_json, version, created_at, updated_at
FROM iot_thing_model
WHERE product_key = #{productKey}
  AND version = #{version}

mapper.update:
UPDATE iot_thing_model
SET model_json = #{modelJson},
    updated_at = CURRENT_TIMESTAMP
WHERE product_key = #{productKey}
  AND version = #{version}
